class Docs @Inject() (cached: Cached, cc: ControllerComponents) extends AbstractController(cc) {
  def show(slug: String) = cached.status(_ => s"/docs/$slug", 200) {
    Action { implicit request =>
      Ok(views.html.doc(articleService.bySlug(slug)))   // runs on a miss only
    }
  }
}
